ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| case {
    ImageFileName=/\\reg\.exe$/i CommandLine=/(?i)\bsave\b/ CommandLine=/(?i)hklm\\(sam|system|security)\b/ | Activity:="HiveDump" ;
    ImageFileName=/\\schtasks\.exe$/i CommandLine=/(?i)\/create/ CommandLine=/(?i)(\/tn\s+\S*(onedrive|googleupdate|edge|adobeupdate|chromeupdate|windowsupdate|defender|office)\S*|\/tr\s+\S*\\(appdata|programdata|users\\public|temp)\\)/ | Activity:="MasqueradedTask" ;
    * | Activity:="drop"
  }
| Activity!="drop"
| UserName!=/\$$/
| groupBy([aid, ComputerName, UserName, Activity, ImageFileName], function=[count(), collect([CommandLine])])
| sort(_count, order=desc)
